namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile was created successfully."),
            CreateNotification("New feature: dark mode is now available."),
        });
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications
                    .Where(n => n.Id > lastId)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Call this periodically to generate fake data.
    /// </summary>
    public Task GenerateRandomNotificationAsync()
    {
        var messages = new[]
        {
            "Someone commented on your post.",
            "You have a new follower!",
            "Your report is ready to download.",
            "Scheduled maintenance tonight at 11 PM.",
            "New message from support team.",
            "Your subscription will renew soon.",
        };

        lock (_lock)
        {
            var msg = messages[Random.Shared.Next(messages.Length)];
            _notifications.Add(CreateNotification(msg));
        }

        return Task.CompletedTask;
    }

    private Notification CreateNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading notifications...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var n in notifications)
        {
            <li>
                <span class="notification-message">@n.Message</span>
                <span class="notification-time">@n.Timestamp.ToString("g")</span>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? notifications;
    private CancellationTokenSource? cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Restore from prerender state, or fetch if this is the first render
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationService.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender,
        // so polling only starts once the page is truly interactive.
        if (firstRender)
        {
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), cancellationToken);

                // Simulate new notifications arriving server-side
                await NotificationService.GenerateRandomNotificationAsync();

                // Fetch the full updated list
                notifications = await NotificationService.GetNotificationsAsync();

                await InvokeAsync(StateHasChanged);
            }
            catch (OperationCanceledException)
            {
                // Expected on disposal — exit cleanly
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

